Object.assign(window.DYLEAN_DATA.files["Library/Init/ByCases.lean"],{"text":"/-\nCopyright (c) 2024 Lean FRO, LLC. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Leonardo de Moura, Mario Carneiro\n-/\nmodule\n\nprelude\npublic meta import Init.Grind.Tactics\npublic import Init.Grind.Tactics\npublic import Init.SimpLemmas\n\npublic section\n\n/-! # by_cases tactic and if-then-else support -/\n\n/--\n`by_cases (h :)? p` splits the main goal into two cases, assuming `h : p` in the first branch, and `h : ¬ p` in the second branch.\n-/\nsyntax \"by_cases \" (atomic(ident \" : \"))? term : tactic\n\nmacro_rules\n  | `(tactic| by_cases $e) => `(tactic| by_cases h : $e)\nmacro_rules\n  | `(tactic| by_cases $h : $e) =>\n    `(tactic| open Classical in refine if $h:ident : $e then ?pos else ?neg)\n\n/-! ## if-then-else -/\n\n@[deprecated ite_true (since := \"2026-07-21\")]\ntheorem if_true {_ : Decidable True} (t e : α) : ite True t e = t := ite_eq_left trivial\n\n@[deprecated ite_false (since := \"2026-07-21\")]\ntheorem if_false {_ : Decidable False} (t e : α) : ite False t e = e := ite_eq_right id\n\ntheorem ite_id [Decidable c] {α} (t : α) : (if c then t else t) = t := by split <;> rfl\n\n/-- A function applied to a `dite` is a `dite` of that function applied to each of the branches. -/\ntheorem apply_dite (f : α → β) (P : Prop) [Decidable P] (x : P → α) (y : ¬P → α) :\n    f (dite P x y) = dite P (fun h => f (x h)) (fun h => f (y h)) := by\n  by_cases h : P <;> simp [h]\n\n/-- A function applied to a `ite` is a `ite` of that function applied to each of the branches. -/\ntheorem apply_ite (f : α → β) (P : Prop) [Decidable P] (x y : α) :\n    f (ite P x y) = ite P (f x) (f y) :=\n  apply_dite f P (fun _ => x) (fun _ => y)\n\n/-- A `dite` whose results do not actually depend on the condition may be reduced to an `ite`. -/\n@[simp] theorem dite_eq_ite {_ : Decidable P} :\n  (dite P (fun _ => a) (fun _ => b)) = ite P a b := rfl\n\n-- Remark: dite and ite are \"defally equal\" when we ignore the proofs.\n@[deprecated dite_eq_ite +typeChanged (since := \"2025-10-29\")]\ntheorem dif_eq_if (c : Prop) {h : Decidable c} {α : Sort u} (t : α) (e : α) : dite c (fun _ => t) (fun _ => e) = ite c t e :=\n  match h with\n  | isTrue _    => rfl\n  | isFalse _   => rfl\n","refs":[[19,42,19,46,"e1d49401e172",false],[19,49,19,55,"dfe60c6dc2a8",false],[29,13,29,21,"d225f020dcaa",false],[30,21,30,30,"ce632cbef893",false],[30,31,30,35,"84a43b20b979",false],[30,49,30,52,"a5da4c1e34d0",false],[30,53,30,57,"84a43b20b979",false],[30,69,30,80,"75ecdc7d4df6",false],[30,81,30,88,"f144592f520d",false],[32,13,32,22,"0fdee4d28397",false],[33,22,33,31,"ce632cbef893",false],[33,32,33,37,"9f7dfdc52bce",false],[33,51,33,54,"a5da4c1e34d0",false],[33,55,33,60,"9f7dfdc52bce",false],[33,72,33,84,"676e6ca755e9",false],[33,85,33,87,"d521f044a9b2",false],[35,16,35,25,"ce632cbef893",false],[38,8,38,18,"cdb36b027bea",true],[38,43,38,52,"ce632cbef893",false],[39,7,39,11,"0c6dc804b3e8",false],[39,21,39,25,"0c6dc804b3e8",false],[43,8,43,17,"8756b90ffa70",true],[43,42,43,51,"ce632cbef893",false],[44,7,44,10,"a5da4c1e34d0",false],[44,20,44,23,"a5da4c1e34d0",false],[45,2,45,12,"cdb36b027bea",false],[48,33,48,42,"ce632cbef893",false],[49,3,49,7,"0c6dc804b3e8",false],[49,39,49,42,"a5da4c1e34d0",false],[49,52,49,55,"4678ade8cd63",false],[53,34,53,43,"ce632cbef893",false],[53,78,53,82,"0c6dc804b3e8",false],[53,113,53,116,"a5da4c1e34d0",false],[55,4,55,10,"9bbb09c82f5a",false],[55,19,55,22,"4678ade8cd63",false],[56,4,56,11,"ead0cba694fa",false],[56,19,56,22,"4678ade8cd63",false]]});
